#!/usr/bin/env python3
"""Stage 4 対照実験: 同一 AST 手法で harness 側 (positive control) と
dev-graph 側 production Python の「実行される定義/呼出」件数を数える。

対象識別子:
  - ヒアリング側: run_chunk        (正本 = run-system-spec-elicit/scripts/apply-spec-transition.py)
  - compile 側:  compile_docset   (正本 = run-system-spec-compile/scripts/compile-spec-doc.py)

除外: tests/ 配下と tests/fixtures/ 配下 (production Python のみを対象にする)。
文字列リテラル・コメント・docstring は AST では拾われないため、
「literal grep が comment/test fixture に当たって 0 と誤報する」事故を構造的に避ける。
"""
from __future__ import annotations

import ast
import json
import pathlib
import sys

IDENTS = ["run_chunk", "compile_docset"]


def is_excluded(path: pathlib.Path) -> bool:
    return "tests" in path.parts


def scan(root: pathlib.Path, exclude_tests: bool) -> dict:
    result = {
        "root": str(root),
        "exclude_tests": exclude_tests,
        "files_scanned": 0,
        "files_unparsable": [],
        "definitions": {k: [] for k in IDENTS},
        "calls": {k: [] for k in IDENTS},
    }
    for path in sorted(root.rglob("*.py")):
        if exclude_tests and is_excluded(path):
            continue
        try:
            tree = ast.parse(path.read_text(encoding="utf-8"), filename=str(path))
        except SyntaxError as exc:  # pragma: no cover - 実測用
            result["files_unparsable"].append(f"{path}: {exc}")
            continue
        result["files_scanned"] += 1
        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and node.name in IDENTS:
                result["definitions"][node.name].append(f"{path}:{node.lineno}")
            elif isinstance(node, ast.ClassDef) and node.name in IDENTS:
                result["definitions"][node.name].append(f"{path}:{node.lineno}")
            elif isinstance(node, ast.Call):
                func = node.func
                name = None
                if isinstance(func, ast.Name):
                    name = func.id
                elif isinstance(func, ast.Attribute):
                    name = func.attr
                if name in IDENTS:
                    result["calls"][name].append(f"{path}:{node.lineno}")
    return result


def main() -> int:
    targets = [
        ("harness_positive_control", pathlib.Path(sys.argv[1]), True),
        ("dev_graph_production", pathlib.Path(sys.argv[2]), True),
    ]
    out = {}
    for label, root, exclude in targets:
        out[label] = scan(root, exclude)
    print(json.dumps(out, ensure_ascii=False, indent=2))

    hp = out["harness_positive_control"]
    dg = out["dev_graph_production"]
    ok = True
    for ident in IDENTS:
        n_pos = len(hp["definitions"][ident])
        if n_pos < 1:
            print(f"MISFIRE: positive control {ident} definitions=0 (検索述語が当たっていない)")
            ok = False
    for ident in IDENTS:
        if len(dg["definitions"][ident]) or len(dg["calls"][ident]):
            print(f"DUP: dev-graph production に {ident} が存在する")
            ok = False
    print("VERDICT:", "PASS" if ok else "FAIL")
    return 0 if ok else 2


if __name__ == "__main__":
    raise SystemExit(main())

