#!/usr/bin/env python3
"""Stage 4 対照実験: 実行可能な Python ロジックの重複を AST で測る。

literal grep はテスト fixture やコメントを拾って「0 件」を偽陽性にするため、
Python AST で **定義 (FunctionDef/AsyncFunctionDef) と呼出 (Call)** だけを数える。

- positive control: harness 側で各語の定義数 N>0 / 呼出数 N>0 が出ることを先に示す。
- negative side: 同じ script で dev-graph の production Python (tests/ 除外) を測り 0 を示す。

usage: ast_probe.py <worktree-root>
"""
import ast
import pathlib
import sys

ROOT = pathlib.Path(sys.argv[1])
PLUGINS = ROOT / "plugins"

# ヒアリング側 1 語 + コンパイル側 1 語 (task.md の要求)
TERMS = {
    "run_chunk": "ヒアリング側: 1 invocation 分のターン列を適用する chunk 実行本体",
    "compile_docset": "コンパイル側: 章別 md + index.md のドキュメントセット組み立て本体",
}


def scan(files):
    """(定義箇所, 呼出箇所) を term ごとに返す。"""
    defs = {t: [] for t in TERMS}
    calls = {t: [] for t in TERMS}
    parsed = 0
    for f in files:
        try:
            tree = ast.parse(f.read_text(encoding="utf-8"), filename=str(f))
        except (SyntaxError, UnicodeDecodeError):
            continue
        parsed += 1
        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and node.name in TERMS:
                defs[node.name].append(f"{f}:{node.lineno}")
            elif isinstance(node, ast.Call):
                fn = node.func
                name = getattr(fn, "id", None) or getattr(fn, "attr", None)
                if name in TERMS:
                    calls[name].append(f"{f}:{node.lineno}")
    return defs, calls, parsed


def collect(plugin, exclude_tests):
    base = PLUGINS / plugin
    out = []
    for f in sorted(base.rglob("*.py")):
        rel = f.relative_to(base).parts
        if "__pycache__" in rel:
            continue
        if exclude_tests and "tests" in rel:
            continue
        out.append(f)
    return out


print(f"探索根 (この worktree のみ): {PLUGINS}")
print()

for label, plugin, exclude_tests in (
    ("positive control = system-spec-harness (全 .py)", "system-spec-harness", False),
    ("negative side  = dev-graph production (.py / tests 除外)", "dev-graph", True),
):
    files = collect(plugin, exclude_tests)
    defs, calls, parsed = scan(files)
    print(f"--- {label} ---")
    print(f"  対象 .py: {len(files)} 件 / AST parse 成功: {parsed} 件")
    for t, why in TERMS.items():
        print(f"  [{t}] {why}")
        print(f"    定義数={len(defs[t])} {defs[t] if defs[t] else ''}")
        print(f"    呼出数={len(calls[t])} {calls[t] if calls[t] else ''}")
    print()

