for label, w, dry, helpflag, cmd in writer_calls:
    kind = "--help" if helpflag else ("dry-run" if dry else "実書込")
    one = " ".join(cmd.split())
    print(f"    [{kind:7s}] {label:14s} {w:22s} {one[:150]}")

print()
print("=" * 74)
print("[3-a-3] canonical writer 以外で変更対象 path を含む Bash (読取/検証のはず)")
print(f"  件数 = {len(other_bash)}")
for label, cmd in other_bash:
    one = " ".join(cmd.split())
    print(f"    {label:14s} {one[:160]}")

